package com.receiptledger.v1.recovery;
import com.receiptledger.v1.validation.ValidationStatus;import org.junit.Test;import static org.junit.Assert.*;
public class RecognitionQualityScorerTest {private final RecognitionQualityScorer s=new RecognitionQualityScorer();@Test public void structurallyValidBeatsTextHeavyMismatch(){QualitySignals good=new QualitySignals(80,24,3,0,true,true,ValidationStatus.PASS);QualitySignals bad=new QualitySignals(260,60,1,1,true,true,ValidationStatus.MISMATCH);assertTrue(s.score(good)>s.score(bad));assertFalse(s.needsRecovery(good));assertTrue(s.needsRecovery(bad));}@Test public void missingDateOrTotalTriggersRecovery(){assertTrue(s.needsRecovery(new QualitySignals(100,20,2,0,false,true,ValidationStatus.PASS)));assertTrue(s.needsRecovery(new QualitySignals(100,20,2,0,true,false,ValidationStatus.PASS)));}}
